    hud.text(20, 86, clean(`${op2.age || ""}  ${op2.job || ""}`), { scale: 1 });
    hud.text(20, 112, clean(op2.hook || "").slice(0, 57), { scale: 1 });
    hud.text(20, 140, clean(op2.objective || "").slice(0, 57), { scale: 1, color: "sand" });
