function drawCard(hud, app, w3, h3) {
  const title = "THE SECOND OPINION CLINIC";
  const tw2 = hud.measure(title, 2).width;
  hud.text((w3 - tw2) / 2, 12, title, { scale: 2, color: "sand" });
  hud.text(20, 58, "KEEP THE PATIENT ALIVE AND TOP THE TEAM SCORE", { scale: 1 });
  hud.text(20, 78, "STICK OR MOUSE MOVES. R2 OR CLICK USES.", { scale: 1 });
  const players = app.session?.infoPlayers?.() || app.cardPlayers || [];
  players.forEach((p3, i3) => {
    const ready = app.session?.card?.ready || [];
    const mark = ready.includes(p3.id) ? "READY" : "WAIT";
    hud.text(24, 110 + i3 * 18, clean(`${p3.name || "SEAT"}  ${mark}`), { scale: 1, color: "white" });
  });
  const left = app.session?.card?.left;
  if (left != null) hud.text(24, h3 - 36, clean(`TIME ${Math.ceil(left / 1e3)}`), { scale: 1 });
  glyphBox(hud, 24, h3 - 24, "CROSS");
  hud.text(56, h3 - 20, "READY    M MORE TIME", { scale: 1 });
}
function drawResults(hud, app, w3, h3) {
  const sim = app.sim;
  if (!sim) return;
  hud.rect(24, 20, w3 - 48, h3 - 40, "ink");
  hud.text(40, 36, clean(sim.title || "CHART"), { scale: 2, color: "sand" });
  const rows = [
    `TIME ${Math.floor(sim.timeLeft)}`,
    `VITALS ${Math.floor(sim.tables?.[0]?.vitals || 0)}`,
    `SCORE ${Math.floor(sim.finalScore || sim.score || 0)}`,
    `MISTAKES ${sim.mistakes}`
  ];
  rows.forEach((row, i3) => hud.text(40, 72 + i3 * 18, row, { scale: 1 }));
  hud.text(w3 - 70, 90, clean(sim.rank || "C"), { scale: 6, color: "sand" });
  const note = app.followLine();
  hud.text(40, h3 - 70, clean(note).slice(0, 57), { scale: 1 });
}
function drawPause(hud, app, w3, h3) {
  hud.rect(16, 16, Math.min(360, w3 - 32), h3 - 32, "ink");
  if (app.mode === "pause") {
    hud.text(28, 28, "PAUSED", { scale: 2, color: "sand" });
    app.pauseItems().forEach((label, i3) => {
      const y3 = 64 + i3 * 22;
      if (i3 === app.focus) hud.rect(24, y3 - 3, 220, 18, "slate");
      hud.text(32, y3, clean(label), { scale: 1 });
    });
    return;
  }
  const tabs = ["BALANCE", "CHEATS", "JUMP", "ACTIONS", "VIEW"];
  hud.text(28, 24, `DEV  ${tabs[app.devTab] || ""}`, { scale: 2, color: "sand" });
  const rows = app.devRows();
  const fit = 12;
  let start = 0;
  if (rows.length > fit) start = Math.min(rows.length - fit, Math.max(0, app.focus - 5));
  for (let i3 = start; i3 < Math.min(rows.length, start + fit); i3++) {
    const y3 = 58 + (i3 - start) * 16;
    if (y3 > h3 - 16) return;
    if (i3 === app.focus) hud.rect(24, y3 - 2, 300, 14, "slate");
    hud.text(30, y3, clean(rows[i3]).slice(0, 48), { scale: 1 });
  }
}
function drawOp(hud, app, w3, h3) {
  const sim = app.sim;
  if (!sim) return;
  hud.rect(0, 0, w3, 22, "ink");
  const shown = sim.shown != null ? sim.shown : Math.round(sim.tables?.[0]?.vitals || 0);
  hud.text(8, 4, `VITALS ${shown}`, { scale: 2, color: shown < 30 ? "red" : "white" });
  const clock = clockText(sim.timeLeft);
  const cw2 = hud.measure(clock, 2).width;
  hud.text((w3 - cw2) / 2, 4, clock, { scale: 2 });
  hud.text(8, 4, `COMP ${Math.floor(sim.composure)}`, { anchor: "top-right", scale: 1, color: "sand" });
  const say = sim.say || app.lineText || "";
  if (say) {
    hud.rect(0, h3 - 36, w3, 36, "ink");
    hud.text(8, h3 - 28, clean(say).slice(0, 57), { scale: 1 });
  }
  drawWheel(hud, w3, h3, sim);
  if (app.hitbox) {
    sim.entities.filter((e104) => !e104.done && !e104.hidden).slice(0, 8).forEach((e104, i3) => {
      hud.text(8, 28 + i3 * 12, clean(`${e104.id} ${e104.kind}`), { scale: 1 });
    });
  }
}
function clockText(seconds) {
  const s3 = Math.max(0, Math.floor(seconds || 0));
  const m4 = Math.floor(s3 / 60);
  const r3 = s3 % 60;
  return `${m4}:${r3 < 10 ? "0" : ""}${r3}`;
}
function drawWheel(hud, w3, h3, sim) {
  const labels = ["SCL", "FRC", "SUT", "DRN", "SYR", "GEL", "LSR", "SCN"];
  const tool = sim.seats?.[0]?.tool || "drain";
  const idx = Math.max(0, TOOLS.indexOf(tool));
  const top = h3 - 172;
  hud.rect(w3 - 56, top - 16, 52, 148, "ink");
  hud.text(w3 - 52, top - 14, `DOSE ${sim.doses}`, { scale: 1 });
  labels.forEach((label, i3) => {
    hud.text(w3 - 50, top + 4 + i3 * 16, label, { scale: 1, color: i3 === idx ? "sand" : "white" });
  });
}
function aboutPageLines(page) {
  if (page === 0) return ABOUT_FIELDS.map(([k2, v3]) => `${k2}: ${v3}`);
  if (page === 1) return TESTING_FEEDBACK;
  if (page === 2) return ENGINE_FEEDBACK;
  if (page === 3) return PROMPT_FEEDBACK;
  return [
    "Pixel Engine MIT",
    "three.js and Rapier",
    "Kenney furniture CC0",
    "All art and audio written in code",
    SOURCE_INFORMATION.source
  ];
}

